from collections import defaultdict
names=list(markers)
aligns={}
for ia,a in enumerate(names):
 for b in names[ia+1:]:
  ptsA=markers[a]; ptsB=markers[b]
  by=defaultdict(list)
  for i,p in enumerate(ptsA):
   for j,q in enumerate(ptsB):
    t=(q[0]-p[0],q[1]-p[1])
    by[t].append((i,j,p,q))
  opts=[]
  for t, pairs in by.items():
   if len(pairs)>=2:
    # actual distinct marker matches
    opts.append((t,pairs))
  if opts:
   aligns[(a,b)]=opts
   print(a,b)
   for t,pairs in opts:
    print(' ',t,'count',len(pairs),'pairs',[(x[0],x[1]) for x in pairs])

shifts={'4':(0,0),'5':(-4,6),'6':(13,-9),'7':(-12,1),'8':(7,-3),'9a':(7,-7),'9b':(-7,-8)}
# get colored coords by component
pieces={}
for color in sorted(set(A.ravel())-{0,2}):
 lab,n=label(A==color)
 for k,sl in enumerate(find_objects(lab),1):
  coords=np.argwhere(lab[sl]==k)+np.array([sl[0].start,sl[1].start])
  # align ordering by known same-color components
  key=str(color) if n==1 else ('9a' if coords[:,0].mean()<10 else '9b')
  pieces[key]=(color,[tuple(x) for x in coords])
out=np.zeros_like(A)
conflicts=[]
for key,(color,coords) in pieces.items():
 dr,dc=shifts[key]
 for r,c in coords:
  q=(int(r+dr),int(c+dc))
  if out[q] not in (0,color): conflicts.append((key,q,int(out[q]),color))
  out[q]=color
print('piece keys',pieces.keys(),'conflicts',conflicts)
allmarks=defaultdict(list)
for key,pts in markers.items():
 dr,dc=shifts[key]
 for p in pts: allmarks[(p[0]+dr,p[1]+dc)].append((key,p))
print('marker destinations',len(allmarks),'counts',sorted(set(map(len,allmarks.values()))),'unshared',[(q,vs) for q,vs in allmarks.items() if len(vs)!=2])
for q in allmarks:
 if out[q]!=0: conflicts.append(('marker',q,out[q]))
 out[q]=2
print('marker-color conflicts',conflicts)
print('\n'.join(' '.join(map(str,row)) for row in out))
